package lk.sliit.nutricare.analytics;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="feedback")public class Feedback{@Id private UUID id;@Column(nullable=false)private UUID patientId;@Column(nullable=false)private UUID practitionerId;@Column(nullable=false)private UUID appointmentId;@Column(nullable=false)private int rating;@Column(length=1500)private String comments;@Column(nullable=false)private Instant createdAt;protected Feedback(){}public Feedback(UUID p,UUID practitioner,UUID appointment,int rating,String comments){id=UUID.randomUUID();patientId=p;practitionerId=practitioner;appointmentId=appointment;this.rating=rating;this.comments=comments;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getPatientId(){return patientId;}public UUID getPractitionerId(){return practitionerId;}public UUID getAppointmentId(){return appointmentId;}public int getRating(){return rating;}public String getComments(){return comments;}public Instant getCreatedAt(){return createdAt;}}
